#!/usr/bin/env python3
"""What's new in v1.4.2: real in-game screenshots, mGBA 0.10.5 engine: the DexNav crash on the v1.4.1 ROM (r09, 115a3204...) and the same search on the v1.4.2 ROM
itself (r10, 7866c59a...) -> data/whatsnew-v1.4.2.json + site/assets/game/whatsnew/v1.4.2/.  usage: whatsnew_v142.py --workspace <VSC>"""
import argparse, hashlib, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
ap = argparse.ArgumentParser(); ap.add_argument("--workspace", default=str(ROOT.parent)); a = ap.parse_args(); WS = Path(a.workspace)
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
R10 = "7866c59a7c101b84eeef03ad1a2ea1b066239e3d9a8a58a5e73a828ea3bc45a5"; R09 = "115a3204c1b2ff8bff6b39fb89418fd80b7674172b5c97974f7b7da8fd806d58"
assert sha(WS / "output/project-blonde-v1.4.2-20261103/Pokemon - Project Blonde.gba") == R10
E_ = "output/project-blonde-v1.4/r10-dexnav-fixes/evidence/screens"
SHOTS = [("crash", f"{E_}/1-v141-dexnav-weezing-crash.png", "The crash, in v1.4.1", "A DexNav search for WEEZING on Cinnabar Island stopped the game on this blue screen. Its encounter level range was stored in reverse."),
         ("search", f"{E_}/2-v142-dexnav-screen.png", "Search for WEEZING", "In v1.4.2, open DexNav on Cinnabar Island, choose WEEZING and press A. Registering it and pressing R in the field works too."),
         ("found", f"{E_}/3-v142-weezing-found.png", "WEEZING found", "The search finds WEEZING in the grass at Lv. 42–43, the same levels as before."),
         ("battle", f"{E_}/4-v142-weezing-battle.png", "Battle and catch", "Walk to it and the battle starts normally. WEEZING can be caught as usual.")]
out = ROOT / "site/assets/game/whatsnew/v1.4.2"; out.mkdir(parents=True, exist_ok=True); rows = []
from PIL import Image
for i, f, t, c in SHOTS:
    src = WS / f; dst = out / f"{i}.png"; shutil.copyfile(src, dst); assert Image.open(dst).size == (240, 160)
    rows.append({"id": i, "file": dst.name, "title": t, "caption": c, "source": f, "sha256": sha(dst), "rom": R09 if i == "crash" else R10})
title = ROOT / "site/assets/game/title/title-v1.4.png"; dst = ROOT / "site/assets/game/title/title-v1.4.2.png"; shutil.copyfile(title, dst)
G = {"_about": "Generated by tools/whatsnew_v142.py - do not edit. Screenshots taken in the mGBA 0.10.5 engine: the crash on the v1.4.1 ROM (r09), the rest on the v1.4.2 ROM itself (r10). The title screen of v1.4.2 still shows v1.4 by owner decision, so the v1.4 title picture is correct.",
     "kind": "story", "before": {"public": "v1.4.1", "build": "r09", "sha256": R09}, "after": {"public": "v1.4.2", "build": "r10", "sha256": R10}, "screenshots_from": {"build": "r10", "sha256": R10, "crash_from": "r09"},
     "heading": "DexNav no longer crashes on WEEZING", "lead": "v1.4.2 is a small bug-fix update. Hunting WEEZING on Cinnabar Island with DexNav now works like any other search.",
     "link": ["/features/dexnav/", "How DexNav works"], "desc": "DexNav no longer crashes when hunting WEEZING on Cinnabar Island",
     "title": {"file": dst.name, "source": "site/assets/game/title/title-v1.4.png", "sha256": sha(dst)}, "shots": rows}
(ROOT / "data/whatsnew-v1.4.2.json").write_text(json.dumps(G, indent=1, ensure_ascii=False) + "\n"); print(len(rows), "shots")
